<?php
require_once __DIR__.'/../config/config.php';require_admin();
$sec=$_GET['section']??'health';$financeView=$_GET['view']??'all';$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  if($sec==='health'){
   $student=(int)$_POST['student_id'];$date=$_POST['date']?:date('Y-m-d');$result='';$medicine=trim($_POST['medicine_name']);$qty=trim($_POST['quantity']);$instructions=trim($_POST['instructions']);$class=trim($_POST['student_class']);$time=trim($_POST['study_time']);$disease=trim($_POST['disease_type']);$healthMonth=trim($_POST['health_month']??'');
   if($disease!=='')$pdo->prepare('INSERT INTO health_exams(student_id,exam_date,result,provider,student_class,study_time,disease_type,report_month) VALUES(?,?,?,?,?,?,?,?)')->execute([$student,$date,$result,'',$class,$time,$disease,$healthMonth]);
   if($medicine!=='')$pdo->prepare('INSERT INTO prescriptions(student_id,prescription_date,medicine_name,dosage,instructions,prescriber) VALUES(?,?,?,?,?,?)')->execute([$student,$date,$medicine,$qty,$instructions,'']);$msg='معلومات صحی ثبت شد.';
  }elseif($sec==='finance'){
   $kind=$_POST['kind']??'expense';
   if($kind==='expense'){$pdo->prepare('INSERT INTO expense_items(expense_date,expense_type,expense_item_name,quantity,price,note) VALUES(?,?,?,?,?,?)')->execute([($_POST['expense_date']??'')?:date('Y-m-d'),trim($_POST['expense_type']),trim($_POST['expense_item_name']??''),$_POST['quantity']?:0,$_POST['price']?:0,trim($_POST['note']??'')]);$msg='مصارفات ثبت شد.';}
   else{$sig='';if(!empty($_FILES['signature']['name'])&&is_uploaded_file($_FILES['signature']['tmp_name'])){$ext=strtolower(pathinfo($_FILES['signature']['name'],PATHINFO_EXTENSION));if(!in_array($ext,['png','jpg','jpeg','webp'],true))throw new Exception('امضاء باید فایل تصویری PNG، JPG یا WEBP باشد.');$sig='sig_'.uniqid().'.'.$ext;move_uploaded_file($_FILES['signature']['tmp_name'],__DIR__.'/../uploads/'.$sig);} $pdo->prepare('INSERT INTO salary_records(name,last_name,father_name,duty,education_level,deduction,payable,note,pay_month,signature_path) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([trim($_POST['name']),trim($_POST['last_name']),trim($_POST['father_name']),trim($_POST['duty']),trim($_POST['education_level']),$_POST['deduction']?:0,$_POST['payable']?:0,trim($_POST['note']),trim($_POST['month']),$sig]);$msg='معاش ثبت شد.';}
  }
 }catch(Exception $e){$err=$e->getMessage();}
}
if($sec==='finance'&&isset($_GET['delete_salary'])){$pdo->prepare('DELETE FROM salary_records WHERE id=?')->execute([(int)$_GET['delete_salary']]);header('Location:'.base_url().'admin/records.php?section=finance#salaries');exit;}
if($sec==='finance'&&isset($_GET['delete_expense'])){$pdo->prepare('DELETE FROM expense_items WHERE id=?')->execute([(int)$_GET['delete_expense']]);header('Location:'.base_url().'admin/records.php?section=finance#expenses');exit;}
if($sec==='health'&&isset($_GET['delete_health'])){$pdo->prepare('DELETE FROM health_exams WHERE id=?')->execute([(int)$_GET['delete_health']]);header('Location:'.base_url().'admin/records.php?section=health#health-history');exit;}
if($sec==='health'&&isset($_GET['delete_prescription'])){$pdo->prepare('DELETE FROM prescriptions WHERE id=?')->execute([(int)$_GET['delete_prescription']]);header('Location:'.base_url().'admin/records.php?section=health#health-history');exit;}
$students=$pdo->query('SELECT id,first_name,father_name FROM students ORDER BY first_name')->fetchAll();$expenses=$pdo->query('SELECT * FROM expense_items ORDER BY id ASC')->fetchAll();$salaries=$pdo->query('SELECT * FROM salary_records ORDER BY id ASC')->fetchAll();
require '../partials/header.php';
?>
<div class="panel form-panel"><div class="section-title"><div><h2><?= $sec==='health'?'بخش صحی':'مصارف و معاشات' ?></h2></div><?php if($sec==='finance'):?><div class="actions"><a class="btn secondary" target="_blank" href="<?=base_url()?>admin/print.php?type=expenses">🖨 چاپ مصارفات</a><a class="btn" target="_blank" href="<?=base_url()?>admin/print.php?type=salaries">🖨 چاپ معاشات</a></div><?php endif;?></div><?php if($msg):?><div class="badge">✓ <?=h($msg)?></div><?php endif;?><?php if($err):?><div class="alert">⚠ <?=h($err)?></div><?php endif;?>
<?php if($sec==='health'):?>
<form method="post"><div class="row"><label>اسم دانش‌آموز *<select required name="student_id"><option value="">انتخاب کنید</option><?php foreach($students as $st):?><option value="<?=$st['id']?>"><?=h($st['first_name'].' — '.$st['father_name'])?></option><?php endforeach;?></select></label><label>تاریخ مراجعه<input type="date" name="date" value="<?=date('Y-m-d')?>"></label><label>از بابت ماه<input name="health_month" placeholder="مثلاً سنبله ۱۴۰۵"></label><label>درجه صنف<input name="student_class"></label><label>تایم درسی<select name="study_time"><option>تایم اول</option><option>تایم دوم</option></select></label><label>نوع مریضی<input name="disease_type"></label><label>نام ادویه تجویز شده<input name="medicine_name"></label><label>مقدار ادویه<input name="quantity"></label><label>دستور مصرف<textarea name="instructions"></textarea></label></div><button>ثبت معلومات صحی</button></form>
<section class="panel health-history" id="health-history"><div class="section-title"><h3>سوابق صحی ثبت‌شده</h3></div><div class="table-scroll"><table><tr><th>دانش‌آموز</th><th>تاریخ مراجعه</th><th>از بابت ماه</th><th>درجه صنف</th><th>تایم درسی</th><th>نوع مریضی</th><th>عملیات</th></tr><?php $hs=$pdo->query("SELECT h.*,s.first_name,s.father_name FROM health_exams h LEFT JOIN students s ON s.id=h.student_id ORDER BY h.id DESC")->fetchAll();foreach($hs as $h):?><tr><td><?=h($h['first_name'].' — '.$h['father_name'])?></td><td><?=h($h['exam_date'])?></td><td><?=h($h['report_month']??'')?></td><td><?=h($h['student_class'])?></td><td><?=h($h['study_time'])?></td><td><?=h($h['disease_type'])?></td><td><a class="btn danger" href="?section=health&delete_health=<?=$h['id']?>" onclick="return confirm('این سابقه صحی حذف شود؟')">🗑 حذف</a></td></tr><?php endforeach;?></table><?php if(!$hs):?><p class="muted">هنوز سابقه‌ای ثبت نشده است.</p><?php endif;?></div><div class="table-scroll health-prescriptions"><table><tr><th>دانش‌آموز</th><th>تاریخ مراجعه</th><th>نام ادویه تجویز شده</th><th>مقدار ادویه</th><th>دستور مصرف</th><th>عملیات</th></tr><?php $ps=$pdo->query("SELECT p.*,s.first_name,s.father_name FROM prescriptions p LEFT JOIN students s ON s.id=p.student_id ORDER BY p.id DESC")->fetchAll();foreach($ps as $p):?><tr><td><?=h($p['first_name'].' — '.$p['father_name'])?></td><td><?=h($p['prescription_date'])?></td><td><?=h($p['medicine_name'])?></td><td><?=h($p['dosage'])?></td><td><?=h($p['instructions'])?></td><td><a class="btn danger" href="?section=health&delete_prescription=<?=$p['id']?>" onclick="return confirm('این نسخه حذف شود؟')">🗑 حذف</a></td></tr><?php endforeach;?></table><?php if(!$ps):?><p class="muted">هنوز ادویه تجویز شده‌ای ثبت نشده است.</p><?php endif;?></div></section>
<?php elseif($sec==='reports'):?>
<section class="panel reports-admin-panel"><div class="section-title"><div><h2>گزارشات کاری</h2><span class="muted">گزارش‌های ماهوار ثبت‌شده توسط استادان.</span></div></div><?php $reps=$pdo->query("SELECT r.*,t.staff_code,t.name,t.last_name FROM teacher_reports r LEFT JOIN teachers t ON t.id=r.teacher_id ORDER BY r.id DESC")->fetchAll();?><div class="reports-grid"><?php foreach($reps as $i=>$rp):?><article class="work-report-card"><div class="work-report-head"><div><strong><?=h(trim($rp['name'].' '.($rp['last_name']??'')))?></strong><span>شماره: <?=h($rp['staff_code'])?> · ماه: <?=h($rp['report_month'])?></span></div><small><?=h($rp['created_at'])?></small></div><div class="work-report-actions"><button type="button" class="report-toggle" data-target="activities-<?=$i?>">فعالیت‌های انجام‌شده</button><button type="button" class="report-toggle" data-target="suggestions-<?=$i?>">پیشنهادات</button></div><div id="activities-<?=$i?>" class="report-detail-box"><b>فعالیت‌های انجام‌شده</b><div><?=nl2br(h($rp['activities_done']??''))?></div></div><div id="suggestions-<?=$i?>" class="report-detail-box"><b>پیشنهادات</b><div><?=nl2br(h($rp['suggestions']??''))?></div></div></article><?php endforeach;?></div><?php if(!$reps):?><p class="muted">هنوز گزارشی ثبت نشده است.</p><?php endif;?></section><script>document.querySelectorAll('.report-toggle').forEach(btn=>btn.addEventListener('click',function(){const target=document.getElementById(this.dataset.target);const card=this.closest('.work-report-card');card.querySelectorAll('.report-detail-box').forEach(x=>{if(x!==target)x.classList.remove('open')});target.classList.toggle('open');}));</script>
<?php else:?>
<?php if($financeView!=='salaries'):?><section id="expenses" class="finance-box"><div class="section-title"><h3>مصارفات</h3><a class="btn secondary" target="_blank" href="<?=base_url()?>admin/print.php?type=expenses">🖨 چاپ جدول مصارفات</a></div><form method="post"><input type="hidden" name="kind" value="expense"><div class="row"><label>تاریخ<input required type="date" name="expense_date" value="<?=date('Y-m-d')?>"></label><label>نوع مصرف<select required name="expense_type"><option value="">انتخاب نوع مصرف</option><option>مصارف اداری</option><option>مصارف تدریسی</option><option>مصارف خیاصی</option><option>مصارف صحی</option><option>مصارف فصل زمستان</option></select></label><label>اسم جنس<input required name="expense_item_name"></label><label>تعداد<input required id="expense-quantity" type="number" step="0.01" name="quantity"></label><label>قیمت<input required id="expense-price" type="number" step="0.01" name="price"></label><label>قیمت مجموعی<input id="expense-total" type="number" step="0.01" readonly></label><label>ملاحظات<textarea name="note"></textarea></label></div><button>ثبت مصارفات</button></form><div class="table-scroll"><table class="excel-table"><tr><th>شماره</th><th>تاریخ</th><th>نوع مصرف</th><th>اسم جنس</th><th>تعداد</th><th>قیمت واحد</th><th>مجموع قیمت</th><th>ملاحظات</th><th>حذف</th></tr><?php $total=0;foreach($expenses as $i=>$e){$line=(float)$e['quantity']*(float)$e['price'];$total+=$line;?><tr><td><?=$i+1?></td><td><?=h($e['expense_date'])?></td><td><?=h($e['expense_type'])?></td><td><?=h($e['expense_item_name']??'')?></td><td><?=h($e['quantity'])?></td><td><?=money($e['price'])?></td><td><?=money($line)?></td><td><?=h($e['note']??'')?></td><td><a class="btn danger" href="?section=finance&delete_expense=<?=$e['id']?>#expenses" onclick="return confirm('این مصرف حذف شود؟')">🗑 حذف</a></td></tr><?php }?><tr class="table-total"><td colspan="7">مجموع قیمت</td><td><?=money($total)?></td><td colspan="2"></td></tr></table></div></section><?php endif;?>
<?php if($financeView!=='expenses'):?><section id="salaries" class="finance-box"><div class="section-title salary-heading"><h3>معاشات</h3><label class="month-inline">از بابت ماه<input required form="salary-form" name="month" placeholder="مثلاً سنبله ۱۴۰۵"></label><a class="btn secondary" target="_blank" href="<?=base_url()?>admin/print.php?type=salaries">🖨 چاپ جدول معاشات</a></div><form id="salary-form" method="post" enctype="multipart/form-data"><input type="hidden" name="kind" value="payroll"><div class="row"><label>اسم کارمند *<input required name="name"></label><label>تخلص<input name="last_name"></label><label>اسم پدر<input name="father_name"></label><label>عنوان وظیفه<input name="duty"></label><label>درجه تحصیل<input name="education_level"></label><label>کسر معاش (افغانی)<input type="number" step="0.01" min="0" name="deduction"></label><label>مبلغ قابل تادیه (افغانی)<input required type="number" step="0.01" min="0" name="payable"></label><label>ملاحظات<textarea name="note"></textarea></label><label>آپلود امضاء<input type="file" name="signature" accept="image/png,image/jpeg,image/webp"></label></div><button>ثبت معاش</button></form><div class="table-scroll"><table class="excel-table"><tr><th>شماره</th><th>اسم کارمند</th><th>تخلص</th><th>اسم پدر</th><th>عنوان وظیفه</th><th>درجه تحصیل</th><th>کسر معاش (افغانی)</th><th>مبلغ قابل تادیه</th><th>از بابت ماه</th><th>ملاحظات</th><th>امضاء</th><th>حذف</th></tr><?php foreach($salaries as $i=>$s):?><tr><td><?=$i+1?></td><td><?=h($s['name'])?></td><td><?=h($s['last_name']??'')?></td><td><?=h($s['father_name'])?></td><td><?=h($s['duty'])?></td><td><?=h($s['education_level'])?></td><td><?=money_usd($s['deduction'])?></td><td><?=money_usd($s['payable'])?></td><td><?=h($s['pay_month'])?></td><td><?=h($s['note'])?></td><td><?php if(!empty($s['signature_path'])&&is_file('../uploads/'.$s['signature_path'])):?><img src="../uploads/<?=h($s['signature_path'])?>" class="signature-uploaded"><?php else:?><span>—</span><?php endif;?></td><td><a class="btn danger" href="?section=finance&delete_salary=<?=$s['id']?>" onclick="return confirm('این معاش حذف شود؟')">حذف</a></td></tr><?php endforeach;?></table></div></section>
<?php endif;?></div><script>document.addEventListener('DOMContentLoaded',function(){const q=document.getElementById('expense-quantity'),p=document.getElementById('expense-price'),t=document.getElementById('expense-total');function calc(){if(q&&p&&t)t.value=((parseFloat(q.value)||0)*(parseFloat(p.value)||0)).toFixed(2);}if(q)q.addEventListener('input',calc);if(p)p.addEventListener('input',calc);calc();});</script><?php endif;?>
<?php require '../partials/footer.php';?>